  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        background: #0b1020;
        color: #f8fafc;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        display: grid;
        place-items: center;
        padding: 2rem;
        background:
          radial-gradient(circle at top left, rgb(56 189 248 / 24%), transparent 32rem),
          radial-gradient(circle at bottom right, rgb(129 140 248 / 22%), transparent 28rem),
          #0b1020;
      }

      .app-shell {
        width: min(100%, 34rem);
      }

      .card {
        padding: 2rem;
        border: 1px solid rgb(148 163 184 / 18%);
        border-radius: 1.5rem;
        background: rgb(15 23 42 / 86%);
        box-shadow: 0 1.5rem 4rem rgb(0 0 0 / 38%);
        backdrop-filter: blur(1rem);
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(1.8rem, 5vw, 2.5rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .intro {
        margin: 0 0 2rem;
        color: #cbd5e1;
        line-height: 1.6;
      }

      fieldset {
        min-width: 0;
        margin: 0;
        padding: 0;
        border: 0;
      }

      legend {
        margin-bottom: 1rem;
        color: #f8fafc;
        font-size: 1.1rem;
        font-weight: 700;
      }

      .form-field {
        margin-bottom: 1.5rem;
      }

      .radio-group {
        display: grid;
        gap: 0.75rem;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        padding: 1rem;
        border: 1px solid rgb(148 163 184 / 22%);
        border-radius: 1rem;
        background: rgb(30 41 59 / 72%);
        color: #e2e8f0;
        cursor: pointer;
        transition:
          border-color 160ms ease,
          background 160ms ease,
          transform 160ms ease;
      }

      .radio-option:hover {
        border-color: #38bdf8;
        background: rgb(51 65 85 / 86%);
        transform: translateY(-1px);
      }

      input[type="radio"] {
        width: 1.15rem;
        height: 1.15rem;
        margin: 0;
        accent-color: #38bdf8;
      }

      input[type="radio"]:focus-visible {
        outline: 3px solid #bae6fd;
        outline-offset: 3px;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.25rem;
        background: linear-gradient(135deg, #38bdf8, #818cf8);
        color: #020617;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 1rem 2rem rgb(56 189 248 / 22%);
      }

      button:hover {
        filter: brightness(1.08);
      }

      button:focus-visible {
        outline: 3px solid #f8fafc;
        outline-offset: 4px;
      }
    </style>
  </head>
  <body>
    <main id="root" class="app-shell"></main>

    <script type="text/babel" data-presets="env,react">
      const notificationOptions = ["Email", "SMS", "Push Notifications"];

      function RadioOption({ value }) {
        const id = `notification-${value.toLowerCase().replace(/\s+/g, "-")}`;

        return (
          <label className="radio-option" htmlFor={id}>
            <input
              id={id}
              name="notificationPreference"
              type="radio"
              value={value}
              required
            />
            <span>{value}</span>
          </label>
        );
      }

      function NotificationForm() {
        return (
          <form className="card" action="#" method="post">
            <h1>Notification Preferences</h1>
            <p className="intro">
              Select the one channel you would like us to use for updates.
            </p>

            <div className="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications?</legend>
                <div className="radio-group">
                  {notificationOptions.map((option) => (
                    <RadioOption key={option} value={option} />
                  ))}
                </div>
              </fieldset>
            </div>

            <button type="submit">Submit preference</button>
          </form>
        );
      }

      function App() {
        return <NotificationForm />;
      }

      ReactDOM.createRoot(document.getElementById("root")).render(<App />);
    </script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
  </body>
</html>
