     <script>
       const notificationOptions = ["Email", "SMS", "Push Notifications"];

       function RadioOption(value) {
         const id = `notification-${value.toLowerCase().replace(/\s+/g, "-")}`;

         return `
           <label class="radio-option" for="${id}">
             <input
               id="${id}"
               name="notificationPreference"
               type="radio"
               value="${value}"
               required
             >
             <span>${value}</span>
           </label>
         `;
       }

       function NotificationForm() {
         return `
           <form class="card" action="#" method="post">
             <h1>Notification Preferences</h1>
             <p class="intro">
               Select the one channel you would like us to use for updates.
             </p>

             <div class="form-field">
               <fieldset>
                 <legend>How do you prefer to receive notifications?</legend>
                 <div class="radio-group">
                   ${notificationOptions.map(RadioOption).join("")}
                 </div>
               </fieldset>
             </div>

             <button type="submit">Submit preference</button>
           </form>
         `;
       }

       function App() {
         return NotificationForm();
       }

       document.getElementById("root").innerHTML = App();
     </script>
